const assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs');
class Node{constructor(){this.listeners={};this.attrs={};this.style={};this.children=[];this.value='';this.checked=false;this.hidden=true;}addEventListener(name,fn){this.listeners[name]=fn;}append(...nodes){this.children.push(...nodes)}setAttribute(k,v){this.attrs[k]=v}getAttribute(k){return k==='href'?this.href:this.attrs[k]}removeAttribute(k){delete this[k];delete this.attrs[k]}}
const ids={};for(const id of ['go','download','code','shelf','books','all','export','shelf-status','status','vault','add-vault'])ids[id]=new Node();let saved={ridiPairCode:'43177:'+ 'a'.repeat(48)},launch;const document={getElementById:id=>ids[id],createElement:()=>new Node(),createTextNode:text=>({text})};const chrome={tabs:{query:async()=>[{id:1,url:'https://ridibooks.com/reading-note/shelf'}]},scripting:{executeScript:async request=>{if(request.func){launch=request;return [];}return [{result:[{id:'1',title:'첫 책'},{id:'2',title:'둘째 책'}]}]}},storage:{local:{get:async()=>({...saved}),set:async value=>{Object.assign(saved,value)}}}};const fetch=async()=>({ok:true,json:async()=>({vaultName:'내 보관함 & 책'})});
vm.runInNewContext(fs.readFileSync(__dirname+'/popup.js','utf8'),{document,chrome,URL,console,fetch});
setTimeout(async()=>{try{const boxes=ids.books.children.map(label=>label.children[0]);assert.equal(boxes.length,2);boxes[0].checked=true;boxes[0].listeners.change();assert.equal(ids.export.href,undefined);await ids['add-vault'].listeners.click();assert.equal(saved.ridiVaults[0].name,'내 보관함 & 책');assert.equal(ids.export.href,'obsidian://ridi-selected?vault=%EB%82%B4%20%EB%B3%B4%EA%B4%80%ED%95%A8%20%26%20%EC%B1%85&books=1');let prevented=false;await ids.export.listeners.click({preventDefault(){prevented=true}});assert.ok(prevented);assert.equal(launch.target.tabId,1);assert.equal(launch.args[0],ids.export.href);ids.all.checked=true;ids.all.listeners.change();assert.match(ids.export.href,/books=1%2C2$/);ids.all.checked=false;ids.all.listeners.change();assert.equal(ids.export.href,undefined);console.log('보관함 연결, 책 선택 및 리디 탭에서 옵시디언 열기 검사 통과');}catch(e){console.error(e);process.exitCode=1}},30);
